# Consume value continuation lines..
def _is_continuation(line):
    if not line:
        return False
    # Use character-level comparison for better performance
    first_char = line[0] if len(line) > 0 else ''
    return first_char == ' ' or first_char == '\t'

while lines and _is_continuation(lines[0]):
